import type { CSSProperties, SVGProps } from "react";
import { CHRISTMAS_MODE } from "../../../config/christmasMode";

/**
 * Staggered twinkle timings for the three garland bulbs of the mobile variant.
 * The blurred glow and the solid core of a single bulb share the same entry so
 * they pulse in perfect sync, while durations and delays vary across bulbs to
 * produce an organic, non-uniform string-light blink (no two bulbs flash in
 * lockstep).
 */
const GARLAND_MOBILE_TWINKLE_TIMINGS: ReadonlyArray<{ duration: string; delay: string }> = [
    { duration: "1.2s", delay: "0s" },
    { duration: "1.4s", delay: "0.25s" },
    { duration: "1.1s", delay: "0.5s" },
];

/**
 * Builds the inline style that animates a bulb only while Christmas mode is
 * active. When the flag is off it returns `undefined` so no animation (and no
 * needless paint work) is applied. Animating opacity keeps the pulse compositor
 * friendly and GPU-accelerated.
 */
const twinkleStyle = (index: number): CSSProperties | undefined =>
    CHRISTMAS_MODE
        ? {
              animationName: "garland-mobile-twinkle",
              animationDuration: GARLAND_MOBILE_TWINKLE_TIMINGS[index].duration,
              animationDelay: GARLAND_MOBILE_TWINKLE_TIMINGS[index].delay,
              animationTimingFunction: "ease-in-out",
              animationIterationCount: "infinite",
          }
        : undefined;

